// Generated from docs/prototype/words.json key "v" (11788 words, packed 5 letters per word). Do not edit by hand.

import { ANSWERS } from './answers';

const PACKED =
  '';

/** Every accepted guess: the valid list plus all answers. */
export const VALID: ReadonlySet<string> = new Set([...(PACKED.match(/.{5}/g) ?? []), ...ANSWERS]);

export const isValidWord = (w: string): boolean => VALID.has(w);

/** Exactly five lowercase letters (prototype okWord). */
export const okWord = (w: unknown): w is string => typeof w === 'string' && /^[a-z]{5}$/.test(w);
